describe('Popover Toggle on Button Click', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should open popover when button is clicked', () => {
    cy.get('[data-testid="popover-trigger-btn"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');
    cy.get('[data-testid="popover-content"]').should('contain.text', 'Popover content');
  });

  it('should close popover when button is clicked again', () => {
    cy.get('[data-testid="popover-trigger-btn"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');
    cy.get('[data-testid="popover-trigger-btn"]').click();
    cy.get('[data-testid="popover-content"]').should('not.be.visible');
  });

  it('should close popover when clicking outside of it', () => {
    cy.get('[data-testid="popover-trigger-btn"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');
    cy.get('body').click(0, 0);
    cy.get('[data-testid="popover-content"]').should('not.be.visible');
  });

  it('should toggle popover multiple times without issues', () => {
    const button = cy.get('[data-testid="popover-trigger-btn"]');
    const popover = cy.get('[data-testid="popover-content"]');

    button.click();
    popover.should('be.visible');

    button.click();
    popover.should('not.be.visible');

    button.click();
    popover.should('be.visible');

    button.click();
    popover.should('not.be.visible');
  });

  it('should maintain popover state when hovering over content', () => {
    cy.get('[data-testid="popover-trigger-btn"]').click();
    cy.get('[data-testid="popover-content"]').should('be.visible');
    cy.get('[data-testid="popover-content"]').trigger('mouseenter');
    cy.get('[data-testid="popover-content"]').should('be.visible');
  });
});
